// Generated by TyraX. Do not edit - regenerated on every build.
// Texture hot reload (debug builds): the editor repaints a texture, re-bakes
// it into bin/ and bumps livetex.bin; this poller re-reads the PNG and
// re-uploads the pixels to the texture's existing GS VRAM allocation.
#include <tyra>
#include <cstdio>
#include <cstring>
#include "scripts/script.hpp"

namespace Global_illumination {
namespace {

constexpr u32 LT_MAGIC = 0x544C5854;  // "TXLT"
constexpr u32 LT_VERSION = 1;
constexpr int LT_PATH = 96;
constexpr int LT_STRIDE = 104;
constexpr int LT_MAX = 64;  // tracked repainted textures

class LiveTex : public Script {
 public:
  void update(ScriptContext& ctx) override {
    if (!ctx.engine) return;
    if (--cooldown_ > 0) return;
    // same cadence reasoning as Live Link: every fopen is a
    // network round-trip under ps2link
    cooldown_ = Tyra::IrxLoader::keepIopResident ? 25 : 6;

    static unsigned char buf[16 + LT_MAX * LT_STRIDE + 4];
    FILE* f = fopen(Tyra::FileUtils::fromCwd("livetex.bin").c_str(), "rb");
    if (!f) return;
    const size_t got = fread(buf, 1, sizeof(buf), f);
    fclose(f);
    if (got < 20) return;
    u32 magic, version, seq, count;
    memcpy(&magic, buf + 0, 4);
    memcpy(&version, buf + 4, 4);
    memcpy(&seq, buf + 8, 4);
    memcpy(&count, buf + 12, 4);
    if (magic != LT_MAGIC || version != LT_VERSION) return;
    if (seq == lastSeq_ || count > (u32)LT_MAX) return;
    if (got != (size_t)(16 + count * LT_STRIDE + 4)) return;
    u32 foot;
    memcpy(&foot, buf + 16 + count * LT_STRIDE, 4);
    if (foot != (seq ^ 0x5A5A5A5AU)) return;

    for (u32 i = 0; i < count; ++i) {
      const unsigned char* r = buf + 16 + i * LT_STRIDE;
      char path[LT_PATH];
      memcpy(path, r, LT_PATH);
      path[LT_PATH - 1] = 0;
      u32 gen;
      memcpy(&gen, r + LT_PATH, 4);
      const int slot = genSlot(path);
      if (slot < 0 || applied_[slot] >= gen) continue;
      applied_[slot] = gen;  // even on failure - a broken file
                             // must not be retried every poll
      reload(ctx, path);
    }
    lastSeq_ = seq;
  }

 private:
  // Re-decode the baked PNG and swap the pixels into every
  // repository texture loaded from that path, then re-send them
  // to the already-allocated VRAM address. Never touches the
  // allocation itself, so it is safe against the bump allocator.
  void reload(ScriptContext& ctx, const char* relPath) {
    auto& repo = ctx.engine->renderer.getTextureRepository();
    auto& core = ctx.engine->renderer.core.texture;
    const std::string full = Tyra::FileUtils::fromCwd(relPath);
    for (Tyra::Texture* t : *repo.getAll()) {
      if (t->vramResident || t->sourcePath != full) continue;
      Tyra::PngLoader loader;
      Tyra::TextureBuilderData* d = loader.load(full);
      if (!d) continue;
      // the format must match what the build shipped: the VRAM
      // texbuffer was sized for it (a missing/torn file comes
      // back as the 8x8 placeholder and fails this check too)
      const bool coreOk = d->width == t->core->width &&
                          d->height == t->core->height &&
                          d->bpp == t->core->bpp;
      // the engine always constructs the clut TextureData - a
      // non-paletted texture just carries a null data pointer
      const bool hadClut = t->clut && t->clut->data != nullptr;
      const bool clutOk =
          ((d->clut != nullptr) == hadClut) &&
          (!hadClut || (d->clutWidth == t->clut->width &&
                        d->clutHeight == t->clut->height &&
                        d->clutBpp == t->clut->bpp));
      if (!coreOk || !clutOk) {
        TYRA_SOFT_ERROR("Live texture reload skipped: ", relPath,
                        " changed size/format - rebuild to apply");
      } else {
        memcpy(t->core->data, d->data,
               ((size_t)t->core->width * t->core->height *
                (u32)t->core->bpp) / 8);
        if (hadClut && d->clut)
          memcpy(t->clut->data, d->clut,
                 ((size_t)t->clut->width * t->clut->height *
                  (u32)t->clut->bpp) / 8);
        // resident -> re-send to the same address now; evicted /
        // not-yet-drawn -> the next useTexture uploads new pixels
        if (core.getAllocatedBuffersByTextureId(t->id).id != 0)
          core.updateTextureInfo(t);
      }
      delete[] d->data;
      if (d->clut) delete[] d->clut;
      delete d;
    }
  }

  // per-path applied generation, keyed by an FNV-1a hash
  int genSlot(const char* path) {
    u32 h = 2166136261U;
    for (const char* c = path; *c; ++c) {
      h ^= (unsigned char)*c;
      h *= 16777619U;
    }
    for (int i = 0; i < n_; ++i)
      if (hash_[i] == h) return i;
    if (n_ >= LT_MAX) return -1;
    hash_[n_] = h;
    applied_[n_] = 0;
    return n_++;
  }

  int cooldown_ = 3;  // offset from LiveLink's poll frame
  u32 lastSeq_ = 0;
  u32 hash_[LT_MAX];
  u32 applied_[LT_MAX];
  int n_ = 0;
};

LiveTex g_liveTex;
static const bool g_liveTexRegistered = []() {
  getScripts().push_back(&g_liveTex);
  return true;
}();

}  // namespace
}  // namespace Global_illumination
